mapper.select:
SELECT crd01_card_id AS card_id , crd01_company_id AS company_id , crd01_bank_cd AS bank_code , f_cdnm('CreditCardCompany', crd01_bank_cd, crd01_company_id, f_sysdate()) AS bank_name , crd01_card_nm AS card_name , crd01_card_no_slip AS card_no_slip , crd01_card_no AS card_no , crd01_fr_dt AS fr_date , crd01_to_dt AS to_date , crd01_close_yn AS close_yn , crd01_card_type AS card_type , f_cdnm('CardType', crd01_card_type, crd01_company_id, f_sysdate()) AS card_type_name , crd01_note AS note , crd01_deposit_id AS deposit_id , f_ast_class_tree_nm(crd01_deposit_id) AS deposit_name , f_emp_kor_nm(crd03_person_id) AS card_manager_name FROM crd01_card LEFT JOIN crd03_trans ON ( crd03_card_id = crd01_card_id AND f_sysdate()::date BETWEEN crd03_fr_dt AND COALESCE(crd03_to_dt,'9999-12-31') ) WHERE crd01_bank_cd LIKE '%' /* AS-IS bankCardCode는 늘 '%' — 은행 코드가 없는(NULL) 카드는 빠진다 */ AND COALESCE(crd01_card_nm,'') || COALESCE(crd01_card_no,'') LIKE #{searchText} AND crd01_company_id = #{companyId}
AND crd01_close_yn = 'true'
AND crd03_person_id = #{managerId}
ORDER BY crd01_card_id

SELECT crd03_person_id AS person_id , f_emp_kor_nm(crd03_person_id) AS name FROM crd01_card INNER JOIN crd03_trans ON ( crd03_card_id = crd01_card_id AND f_sysdate()::date BETWEEN crd03_fr_dt AND COALESCE(crd03_to_dt,'9999-12-31') ) WHERE crd01_company_id = #{companyId}
AND crd01_close_yn = 'true'
GROUP BY crd03_person_id

SELECT COUNT(*)
  FROM crd02_data
 WHERE crd02_card_no like #{cardNo}
   AND crd02_company_id = #{companyId}

mapper.delete:
DELETE FROM crd01_card
 WHERE crd01_card_id    = #{cardId}
   AND crd01_company_id = #{companyId}

mapper.update:
UPDATE crd03_trans
   SET crd03_person_id = #{req.personId},
       crd03_fr_dt     = #{req.frDt},
       crd03_to_dt     = #{req.toDt},
       crd03_use_yn    = #{req.useYn},
       crd03_public_yn = #{req.publicYn}
 WHERE crd03_trans_id = #{req.transId}
   AND crd03_card_id  = #{cardId}

mapper.delete:
DELETE FROM crd03_trans
 WHERE crd03_card_id = #{cardId}
   AND crd03_trans_id IN
#{id}
